// devices.offline.due — R15. Generated by `pnpm gen:query`; acceptance cases added.
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import {
  aStaffActor,
  createFakeClock,
  createTestDatabase,
  runAsOwner,
  type TestDatabase,
} from '@ocs/testing';
import { Forbidden, openTestKernel, systemActor, type TestKernel } from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { registerDevice } from '../commands/register-device.ts';
import { offlineDue } from '../queries/offline-due.ts';

const job = systemActor('alerts');
const pm = aStaffActor({ roles: ['pm'] });
const clock = createFakeClock(new Date('2026-11-04T12:00:00Z'));
const hoursAgo = (h: number) => new Date(clock.now().getTime() - h * 3_600_000);
let testDb: TestDatabase;
let t: TestKernel;
let live: string;
let notLive: string;

/** Platform state as the sync would leave it (the sync command has its own tests). */
const seen = (sn: string, status: 'online' | 'offline' | 'disabled', offlineSince: Date | null) =>
  runAsOwner(testDb.url, `UPDATE device SET platform_status = $2, offline_since = $3 WHERE sn = $1`, [
    sn,
    status,
    offlineSince,
  ]);

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url, { clock: clock.now });
  const setup = aStaffActor({ roles: ['director'] });
  t.grant(setup, createClient.permission, createSite.permission);
  t.grant(pm, registerDevice.permission);
  t.grant(job, offlineDue.permission);
  const a = await t.kernel.execute(createClient, setup, { shortCode: 'CLIENTA', name: 'Client A' }, 'test');
  const place = { countryCode: 'ES', cityCode: 'MAD', cityName: 'Madrid', name: 'Mall A', standard: 'L' };
  ({ id: live } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
  ({ id: notLive } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
  await runAsOwner(testDb.url, `UPDATE site SET device_alerts_enabled = true, pm_id = $2 WHERE id = $1`, [
    live,
    pm.id,
  ]);
  for (const [siteId, sn] of [
    [live, 'SN-0001'],
    [live, 'SN-0002'],
    [live, 'SN-0003'],
    [live, 'SN-0004'],
    [notLive, 'SN-0005'],
  ] as const) {
    await t.kernel.execute(registerDevice, pm, { siteId, sn, model: 'G6' }, 'test');
  }
  await seen('SN-0001', 'offline', hoursAgo(30));
  await seen('SN-0002', 'offline', hoursAgo(23));
  await seen('SN-0003', 'online', null);
  await seen('SN-0004', 'disabled', null);
  await seen('SN-0005', 'offline', hoursAgo(72));
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('devices.offline.due', () => {
  it('refuses anyone but the system actor', async () => {
    await expect(t.kernel.read(offlineDue, pm, {})).rejects.toBeInstanceOf(Forbidden);
  });

  it('lists devices offline more than 24 h, only on projects whose alerts are on, with the PM', async () => {
    expect(await t.kernel.read(offlineDue, job, {})).toEqual([
      expect.objectContaining({ sn: 'SN-0001', siteId: live, pmId: pm.id, offlineSince: hoursAgo(30) }),
    ]);
  });

  it('a device crosses the 24 h line as time passes; ticking the box brings in a mall that went live', async () => {
    clock.advance({ hours: 2 });
    await runAsOwner(testDb.url, `UPDATE site SET device_alerts_enabled = true WHERE id = $1`, [notLive]);
    const due = await t.kernel.read(offlineDue, job, {});
    expect(due.map((d) => d.sn)).toEqual(['SN-0005', 'SN-0001', 'SN-0002']);
    expect(due[0]?.pmId).toBeNull();
  });
});
